package bus;

import dao.NhanVienDAO;
import dao.TaiKhoanDAO;
import entity.NhanVien;
import entity.TaiKhoan;
import utils.PasswordHasher;

import java.sql.SQLException;
import java.security.SecureRandom;

/**
 * Controller xử lý logic nghiệp vụ Đăng nhập, Xác thực bảo mật & Quên mật khẩu.
 * Đăng nhập bằng Số điện thoại nhân viên + Mật khẩu băm SHA-256.
 */
public class DangNhapBus {
    private static final SecureRandom SECURE_RANDOM = new SecureRandom();

    private final TaiKhoanDAO taiKhoanDAO;
    private final NhanVienDAO nhanVienDAO;
    private static NhanVien currentUser = null;

    public DangNhapBus() {
        this.taiKhoanDAO = new TaiKhoanDAO();
        this.nhanVienDAO = new NhanVienDAO();
    }

    /**
     * Kết quả trả về sau khi xác thực đăng nhập.
     */
    public static class KetQuaDangNhap {
        private final boolean thanhCong;
        private final String thongDiep;
        private final NhanVien nhanVien;

        public KetQuaDangNhap(boolean thanhCong, String thongDiep, NhanVien nhanVien) {
            this.thanhCong = thanhCong;
            this.thongDiep = thongDiep;
            this.nhanVien = nhanVien;
        }

        public boolean isThanhCong() {
            return thanhCong;
        }

        public String getThongDiep() {
            return thongDiep;
        }

        public NhanVien getNhanVien() {
            return nhanVien;
        }
    }

    /**
     * Chuẩn hóa số điện thoại nhập vào (xóa dấu cách, gạch nối, định dạng quốc tế +84 -> 0).
     */
    public String chuanHoaSoDienThoai(String sdt) {
        if (sdt == null) return "";
        String s = sdt.trim().replaceAll("[^0-9+]", "");
        if (s.startsWith("+84")) {
            s = "0" + s.substring(3);
        }
        return s;
    }

    /**
     * Xử lý xác thực đăng nhập nhân viên bằng Số điện thoại và Mật khẩu.
     * Mật khẩu được tự động băm SHA-256 trước khi đối chiếu trong CSDL.
     */
    public KetQuaDangNhap xuLyDangNhap(String soDienThoaiHoacMa, String matKhau) {
        if (soDienThoaiHoacMa == null || soDienThoaiHoacMa.trim().isEmpty()) {
            return new KetQuaDangNhap(false, "Vui lòng nhập Số điện thoại nhân viên!", null);
        }
        if (matKhau == null || matKhau.trim().isEmpty()) {
            return new KetQuaDangNhap(false, "Vui lòng nhập mật khẩu!", null);
        }

        String inputUser = soDienThoaiHoacMa.trim();
        String sdt = chuanHoaSoDienThoai(inputUser);
        String passHash = PasswordHasher.hashSHA256(matKhau.trim());

        try {
            // 1. Thử xác thực theo số điện thoại
            TaiKhoan tk = taiKhoanDAO.kiemTraDangNhap(sdt, passHash);

            // 2. Nếu không tìm thấy bằng SĐT, thử xác thực bằng mã tài khoản (NVxxx) cho tương thích
            if (tk == null && inputUser.toUpperCase().startsWith("NV")) {
                TaiKhoan tkMa = taiKhoanDAO.findByMaTaiKhoan(inputUser.toUpperCase());
                if (tkMa != null && tkMa.isTrangThaiHoatDong() && passHash.equalsIgnoreCase(tkMa.getMatKhau())) {
                    tk = tkMa;
                }
            }

            if (tk != null) {
                NhanVien nv = nhanVienDAO.findByMaNhanVien(tk.getMaTaiKhoan());
                if (nv == null) {
                    nv = nhanVienDAO.findBySoDienThoai(tk.getSoDienThoai());
                }
                if (nv != null) {
                    nv.setTaiKhoan(tk);
                    currentUser = nv;
                    utils.UserSession.initSession(nv);
                    return new KetQuaDangNhap(true, "Đăng nhập thành công!", nv);
                } else {
                    return new KetQuaDangNhap(false, "Tài khoản [" + tk.getMaTaiKhoan() + "] chưa được liên kết thông tin Nhân viên!", null);
                }
            } else {
                // Kiểm tra lý do chi tiết để hỗ trợ người dùng
                TaiKhoan tonTai = taiKhoanDAO.findBySoDienThoai(sdt);
                if (tonTai == null && inputUser.toUpperCase().startsWith("NV")) {
                    tonTai = taiKhoanDAO.findByMaTaiKhoan(inputUser.toUpperCase());
                }

                if (tonTai == null) {
                    return new KetQuaDangNhap(false, "Số điện thoại / Mã nhân viên hoặc mật khẩu không chính xác!", null);
                } else if (!tonTai.isTrangThaiHoatDong()) {
                    return new KetQuaDangNhap(false, "Tài khoản của nhân viên này đang bị khóa hoặc ngừng hoạt động!", null);
                } else {
                    return new KetQuaDangNhap(false, "Mật khẩu không chính xác! Vui lòng thử lại hoặc sử dụng 'Quên mật khẩu'.", null);
                }
            }
        } catch (SQLException e) {
            System.err.println("[DangNhapBus] Lỗi SQL khi xác thực: " + e.getMessage());
            return new KetQuaDangNhap(false, "Không thể kết nối đến máy chủ CSDL SQL Server:\n" + e.getMessage() + "\nVui lòng kiểm tra lại dịch vụ SQL Server!", null);
        }
    }

    /**
     * Xác thực thông tin Quên mật khẩu (kiểm tra SĐT và Email có khớp trong CSDL không).
     */
    public NhanVien xacThucQuenMatKhau(String soDienThoai, String email) {
        if (soDienThoai == null || email == null) return null;
        String sdt = chuanHoaSoDienThoai(soDienThoai);
        String mail = email.trim();
        if (sdt.isEmpty() || mail.isEmpty()) return null;

        try {
            TaiKhoan tk = taiKhoanDAO.findBySoDienThoaiVaEmail(sdt, mail);
            if (tk != null && tk.isTrangThaiHoatDong()) {
                NhanVien nv = nhanVienDAO.findByMaNhanVien(tk.getMaTaiKhoan());
                if (nv == null) {
                    nv = nhanVienDAO.findBySoDienThoai(tk.getSoDienThoai());
                }
                if (nv != null) {
                    nv.setTaiKhoan(tk);
                    return nv;
                }
            }
        } catch (SQLException e) {
            System.err.println("[DangNhapBus] Lỗi xacThucQuenMatKhau: " + e.getMessage());
        }
        return null;
    }

    /**
     * Sinh mã OTP ngẫu nhiên 6 chữ số phục vụ xác thực quên mật khẩu.
     */
    public String sinhMaOTP() {
        int otp = 100000 + SECURE_RANDOM.nextInt(900000);
        return String.valueOf(otp);
    }

    /**
     * Đặt lại mật khẩu mới sau khi xác thực OTP thành công.
     */
    public boolean datLaiMatKhau(String soDienThoai, String matKhauMoi) {
        if (soDienThoai == null || matKhauMoi == null || matKhauMoi.trim().length() < 6) {
            return false;
        }
        String sdt = chuanHoaSoDienThoai(soDienThoai);
        String hash = PasswordHasher.hashSHA256(matKhauMoi.trim());
        try {
            return taiKhoanDAO.doiMatKhauTheoSoDienThoai(sdt, hash);
        } catch (SQLException e) {
            System.err.println("[DangNhapBus] Lỗi datLaiMatKhau: " + e.getMessage());
            return false;
        }
    }

    /**
     * Đổi mật khẩu tài khoản người dùng hiện tại (băm SHA-256).
     */
    public boolean doiMatKhau(String maHoacSdt, String matKhauCu, String matKhauMoi) {
        if (maHoacSdt == null || matKhauCu == null || matKhauMoi == null) return false;
        if (matKhauMoi.trim().length() < 6) return false;

        String oldHash = PasswordHasher.hashSHA256(matKhauCu.trim());
        String newHash = PasswordHasher.hashSHA256(matKhauMoi.trim());

        try {
            TaiKhoan tk = taiKhoanDAO.findBySoDienThoai(maHoacSdt);
            if (tk == null) {
                tk = taiKhoanDAO.findByMaTaiKhoan(maHoacSdt);
            }
            if (tk != null && oldHash.equalsIgnoreCase(tk.getMatKhau())) {
                boolean ok = taiKhoanDAO.doiMatKhau(tk.getMaTaiKhoan(), newHash);
                if (ok && currentUser != null && currentUser.getTaiKhoan() != null) {
                    currentUser.getTaiKhoan().setMatKhau(newHash);
                }
                return ok;
            }
            return false;
        } catch (SQLException e) {
            System.err.println("[DangNhapBus] Lỗi đổi mật khẩu SQL: " + e.getMessage());
            return false;
        }
    }

    /**
     * Lấy người dùng đang đăng nhập trong phiên làm việc hiện tại.
     */
    public static NhanVien getCurrentUser() {
        return currentUser;
    }

    /**
     * Gán người dùng hiện tại.
     */
    public static void setCurrentUser(NhanVien nv) {
        currentUser = nv;
        utils.UserSession.initSession(nv);
    }

    /**
     * Đăng xuất khỏi hệ thống.
     */
    public static void dangXuat() {
        currentUser = null;
        utils.UserSession.clearSession();
    }
}

package gui;

import bus.DangNhapBus;
import entity.NhanVien;
import utils.IconHelper;
import utils.ThemeColors;
import utils.UserSession;

import javax.swing.*;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.LineBorder;
import java.awt.*;
import java.awt.event.ActionListener;
import java.awt.event.KeyEvent;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;

/**
 * Giao diện làm việc chính (Main Dashboard) của Hệ thống Quản lý Cửa hàng Thú cưng.
 * Áp dụng kiến trúc điều hướng kép (Dual Navigation) bám sát 100% Slide 17 IUH:
 * - Hệ thống Menu 6 nhóm chức năng chuẩn Slide 17: Hệ thống, Danh mục, Cập nhật, Xử lý, Tìm kiếm, Báo biểu.
 * - Thanh thực đơn JMenuBar trên đỉnh với phím tắt Alt+1 đến Alt+6 và phân quyền RBAC chặt chẽ.
 * - Thanh bên Sectional Sidebar phân nhóm 6 cụm chức năng có Section Header rõ ràng, hỗ trợ cuộn mượt mà.
 * - Tông màu Warm Peach / Soft Apricot / Nude sang trọng, FlatLaf hiện đại, khử răng cưa toàn diện.
 */
public class MainDashboard extends JFrame {

    private static MainDashboard currentInstance = null;

    private final NhanVien currentUser;
    private JPanel pnlContentCards;
    private CardLayout cardLayout;

    private final List<JButton> menuButtons = new ArrayList<>();
    private final List<String> menuIconNames = new ArrayList<>();
    private final List<String> menuCardNames = new ArrayList<>();

    // Các màn hình con nghiệp vụ
    private TongQuanPanel tongQuanPanel;
    private BanHangPOSPanel banHangPOSPanel;
    private QuanLyLichHenPanel quanLyLichHenPanel;
    private ThuCungDichVuPanel thuCungDichVuPanel;
    private KhoLoHangPanel khoLoHangPanel;
    private QuanLyNhanVienPanel quanLyNhanVienPanel;
    private BanGiaoCaPanel banGiaoCaPanel;
    private LichPhanCaPanel lichPhanCaPanel;
    private PetHotelPanel petHotelPanel;
    private DoiTraHangPanel doiTraHangPanel;

    // Tên các thẻ Card
    public static final String CARD_TONG_QUAN = "CARD_TONG_QUAN";
    public static final String CARD_POS = "CARD_POS";
    public static final String CARD_LICH_HEN = "CARD_LICH_HEN";
    public static final String CARD_PET_HOTEL = "CARD_PET_HOTEL";
    public static final String CARD_THU_CUNG = "CARD_THU_CUNG";
    public static final String CARD_KHO = "CARD_KHO";
    public static final String CARD_NHAN_VIEN = "CARD_NHAN_VIEN";
    public static final String CARD_GIAO_CA = "CARD_GIAO_CA";
    public static final String CARD_PHAN_CA = "CARD_PHAN_CA";
    public static final String CARD_DOI_TRA = "CARD_DOI_TRA";

    /**
     * Constructor mặc định (dùng cho chạy thử nghiệm hoặc standalone preview).
     */
    public MainDashboard() {
        this(UserSession.getCurrentUser());
    }

    /**
     * Constructor chính với nhân viên đã xác thực từ LoginForm.
     */
    public MainDashboard(NhanVien nhanVien) {
        if (nhanVien == null || nhanVien.getTaiKhoan() == null) {
            throw new IllegalStateException("Phải đăng nhập hợp lệ trước khi mở Dashboard");
        }
        this.currentUser = nhanVien;
        UserSession.initSession(this.currentUser);
        currentInstance = this;
        khoiTaoGiaoDien();
    }

    private void khoiTaoGiaoDien() {
        setTitle("HỆ THỐNG QUẢN LÝ CỬA HÀNG THÚ CƯNG - " + UserSession.getFullName() + " [" + UserSession.getRoleCode() + "]");
        setSize(1360, 880);
        setMinimumSize(new Dimension(1120, 720));
        setLocationRelativeTo(null);
        setExtendedState(JFrame.MAXIMIZED_BOTH);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLayout(new BorderLayout());
        getContentPane().setBackground(ThemeColors.BACKGROUND);

        UserSession.Role role = UserSession.getCurrentRole();

        // 1. Thanh thực đơn đỉnh màn hình 6 nhóm chức năng (JMenuBar chuẩn Slide 17 IUH)
        setJMenuBar(taoJMenuBarHuongChucNang(role));

        // 2. Vùng đỉnh gồm Header thương hiệu và thanh Navigation Bar dạng Pill Tabs
        JPanel pnlNorth = new JPanel(new BorderLayout());
        pnlNorth.add(taoTopHeader(), BorderLayout.NORTH);
        pnlNorth.add(taoTopNavigationBar(role), BorderLayout.SOUTH);
        add(pnlNorth, BorderLayout.NORTH);

        // 3. Đã giải phóng hoàn toàn Sidebar bên trái (Không add vào BorderLayout.WEST)
        // Dành trọn vẹn 100% diện tích chiều ngang cho POS và các Bảng dữ liệu!

        // 4. Vùng nội dung chính (Center CardLayout Panels - Áp dụng Lazy Loading On-Demand)
        cardLayout = new CardLayout();
        pnlContentCards = new JPanel(cardLayout);
        pnlContentCards.setBackground(ThemeColors.BACKGROUND);
        add(pnlContentCards, BorderLayout.CENTER);

        // 5. Thanh trạng thái dưới cùng (South Status Bar)
        add(taoBottomStatusBar(), BorderLayout.SOUTH);

        // Mặc định nạp duy nhất màn hình phù hợp theo vai trò vừa đăng nhập (Mở app < 1.0 giây)
        chonManHinhMacDinhTheoVaiTro();
    }

    // =========================================================================
    // 1. THANH THỰC ĐƠN ĐỈNH MÀN HÌNH (JMENUBAR 6 NHÓM CHỨC NĂNG CHUẨN SLIDE 17)
    // =========================================================================
    private JMenuBar taoJMenuBarHuongChucNang(UserSession.Role role) {
        JMenuBar menuBar = new JMenuBar();
        menuBar.setBackground(ThemeColors.SURFACE);
        menuBar.setBorder(BorderFactory.createMatteBorder(0, 0, 1, 0, ThemeColors.BORDER));

        // Nhóm 1: Hệ thống (Alt + 1)
        JMenu mnuHeThong = taoMenuChinh("1. Hệ thống", KeyEvent.VK_1, IconHelper.SETTINGS);
        mnuHeThong.add(taoMenuItem("Bảng điều khiển Tổng quan (Dashboard)", IconHelper.BAR_CHART, KeyStroke.getKeyStroke(KeyEvent.VK_F5, 0), UserSession.canAccess(CARD_TONG_QUAN), e -> dieuHuongSangChucNang(CARD_TONG_QUAN)));
        mnuHeThong.addSeparator();
        mnuHeThong.add(taoMenuItem("Đổi mật khẩu tài khoản", IconHelper.KEY, KeyStroke.getKeyStroke(KeyEvent.VK_M, Toolkit.getDefaultToolkit().getMenuShortcutKeyMaskEx()), true, e -> thucHienDoiMatKhau()));
        mnuHeThong.add(taoMenuItem("Phân quyền vai trò", IconHelper.SHIELD, KeyStroke.getKeyStroke(KeyEvent.VK_P, Toolkit.getDefaultToolkit().getMenuShortcutKeyMaskEx()), UserSession.canAccessNhom1HeThongPhanQuyen(), e -> dieuHuongSangChucNang(CARD_NHAN_VIEN)));
        mnuHeThong.add(taoMenuItem("Bàn giao ca / Chốt két", IconHelper.CLIPBOARD_CHECK, KeyStroke.getKeyStroke(KeyEvent.VK_G, Toolkit.getDefaultToolkit().getMenuShortcutKeyMaskEx()), UserSession.canAccessNhom1GiaoCa(), e -> dieuHuongSangChucNang(CARD_GIAO_CA)));
        mnuHeThong.addSeparator();
        mnuHeThong.add(taoMenuItem("Đăng xuất tài khoản", IconHelper.LOG_OUT, KeyStroke.getKeyStroke(KeyEvent.VK_Q, Toolkit.getDefaultToolkit().getMenuShortcutKeyMaskEx()), true, e -> xuLyDangXuat()));
        mnuHeThong.add(taoMenuItem("Thoát ứng dụng", IconHelper.TRASH, KeyStroke.getKeyStroke(KeyEvent.VK_F4, KeyEvent.ALT_DOWN_MASK), true, e -> thucHienThoatHeThong()));
        menuBar.add(mnuHeThong);

